// Verifies the HMAC Convex puts on every loan event: hex(HMAC_SHA256(secret, `${timestamp}.${rawBody}`)).
// The secret comes from the LENDLOOP_SHARED_SECRET env var, never from this workflow.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_SHARED_SECRET is not configured');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '').toLowerCase();

// Prefer the exact raw bytes; fall back to re-serialising the parsed body
// (identical for Convex's compact JSON.stringify output).
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  raw = JSON.stringify(item.json.body);
}

const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() - Number(timestamp)) < 5 * 60 * 1000;
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const valid = fresh && signature.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));

if (!valid) return [{ json: { valid: false, reason: fresh ? 'bad signature' : 'stale or missing timestamp' } }];

const body = JSON.parse(raw);
// Keep only the fields this workflow needs (data minimisation).
return [{ json: {
  valid: true,
  eventId: body.eventId,
  event: body.event,
  toolName: body.toolName,
  startDate: body.startDate,
  endDate: body.endDate,
  recipient: { firstName: body.recipient.firstName, email: body.recipient.email },
} }];

// Convex retries until it gets a 2xx, so the same eventId can arrive twice if a
// response was lost. Remember recent ids and skip duplicates.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const e = $input.first().json;
const now = Date.now();
for (const [id, at] of Object.entries(store.seen)) if (now - at > 7 * 864e5) delete store.seen[id];
if (store.seen[e.eventId]) return [{ json: { duplicate: true, eventId: e.eventId } }];
store.seen[e.eventId] = now;

const range = `${e.startDate} to ${e.endDate}`;
const text = {
  request_created: `Hi ${e.recipient.firstName}, a neighbour asked to borrow your ${e.toolName} (${range}). Open LendLoop to approve or decline.`,
  request_cancelled: `Hi ${e.recipient.firstName}, the request for your ${e.toolName} (${range}) was cancelled.`,
  request_approved: `Good news ${e.recipient.firstName}! Your request for the ${e.toolName} (${range}) was approved.`,
  request_declined: `Hi ${e.recipient.firstName}, your request for the ${e.toolName} (${range}) was declined.`,
  loan_returned: `Thanks ${e.recipient.firstName}! The ${e.toolName} has been marked as returned.`,
}[e.event] || `LendLoop update about ${e.toolName}.`;

return [{ json: { duplicate: false, eventId: e.eventId, to: e.recipient.email, subject: 'LendLoop update', text } }];

// Mock channel: logs the message. Swap this node for Send Email / Slack / Discord
// (with an n8n credential) to deliver for real.
const m = $input.first().json;
if (m.duplicate) return [{ json: { ok: true, duplicate: true } }];
console.log(`[LendLoop notification] to=${m.to} :: ${m.text}`);
return [{ json: { ok: true, delivered: 'mock-log', eventId: m.eventId } }];
